"""AI coding agents and developer-agent platform suites."""


def module(slug: str, label: str, tasks: str):
    return slug, label, [task.strip() for task in tasks.split("|") if task.strip()]


def journey(name, section, create, fields, submit, record, follow):
    return name, section, create, fields, submit, record, follow


BOUNDARY = (
    "Use disposable synthetic repositories and mock integrations only. Never expose real credentials, "
    "modify production repositories, or publish/merge changes during a test run."
)


def product(root, key, display, prefix, accent, modules, journeys):
    return {
        "root": root,
        "key": key,
        "display": display,
        "prefix": prefix,
        "accent": accent,
        "industryDomain": "developer-tools",
        "safetyNote": BOUNDARY,
        "modules": modules,
        "journeys": journeys,
    }


